10:   query?: string;
11:   activeSessionId?: string;
12:   onSelect?: (session: SessionSummaryDto) => void;
13: }) {
14:   const [expanded, setExpanded] = useState(true);
15:   const [sessions, setSessions] = useState<SessionSummaryDto[]>([]);
16:   const [loading, setLoading] = useState(true);
17:   const [error, setError] = useState('');
18:   const [revision, setRevision] = useState(0);
19:   const refresh = useCallback(() => setRevision(value => value + 1), []);
20: 
21:   useEffect(() => {
22:     window.addEventListener('focus', refresh);
23:     return () => window.removeEventListener('focus', refresh);
24:   }, [refresh]);
25: 
26:   useEffect(() => {
27:     let cancelled = false;
28:     setLoading(true);
29:     setError('');
30:     fetchFeishuConversations().then(value => {
31:       if (!cancelled) setSessions(value);
32:     }).catch(reason => {
33:       if (!cancelled) setError(reason instanceof Error ? reason.message : '读取飞书对话失败');
34:     }).finally(() => { if (!cancelled) setLoading(false); });
35:     return () => { cancelled = true; };
36:   }, [revision]);
37: 
38:   const visible = sessions.filter(session => session.title.toLowerCase().includes(query.trim().toLowerCase()));
39:   return (
40:     <section className={sidebar.sectionGroup} aria-label="飞书对话">
41:       <div className={sidebar.groupHeader}>
42:         <button type="button" className={sidebar.groupTitleBtn} aria-expanded={expanded}
43:           onClick={() => setExpanded(value => !value)}>
44:           {expanded ? <ChevronDown size={13} /> : <ChevronRight size={13} />}
45:           <span className={sidebar.groupTitle}>飞书对话</span>
46:           <span className={styles.count}>{sessions.length}</span>
47:         </button>
48:         <button type="button" className={sidebar.iconBtnSmall} aria-label="刷新飞书对话"
49:           title="刷新飞书对话" onClick={refresh} disabled={loading}><RefreshCw size={13} /></button>
50:       </div>
51:       {expanded && <div className={sidebar.sessionList}>
52:         {loading && <p className={sidebar.emptyText} role="status">正在读取飞书对话…</p>}
53:         {error && <div className={styles.feedback} role="alert">{error}
54:           <button type="button" onClick={refresh}>重试</button></div>}
55:         {!loading && !error && visible.length === 0 && <p className={sidebar.emptyText}>
56:           {query.trim() ? '没有匹配的飞书对话' : '暂无飞书对话'}</p>}
57:         {!loading && !error && visible.map(session => <button type="button" key={session.id}
58:           className={`${styles.session} ${session.id === activeSessionId ? styles.active : ''}`} aria-current={session.id === activeSessionId ? 'page' : undefined} onClick={() => onSelect?.(session)} title={session.title}>
59:           <MessageSquare size={14} /><span>{session.title}</span>
60:         </button>)}
61:       </div>}
62:     </section>
63:   );
64: }

