184: fn validate_remote_url(url: &str) -> Result<(), String> {
185:     let (scheme, rest) = url
186:         .split_once("://")
187:         .ok_or("请输入完整的后端地址，例如 http://192.168.1.10:8081")?;
188:     let authority = rest.split('/').next().unwrap_or_default();
189:     let base_path = &rest[authority.len()..];
190:     if !matches!(scheme, "http" | "https")
191:         || authority.is_empty()
192:         || !matches!(base_path, "" | "/")
193:         || authority.contains('@')
194:         || authority.contains('?')
195:         || authority.contains('#')
196:         || rest.contains('?')
197:         || rest.contains('#')
198:         || url.chars().any(char::is_whitespace)
199:     {
200:         return Err("后端地址仅支持不含账号、查询参数或片段的 HTTP/HTTPS 地址".into());
201:     }
