271: /// 启动本地 sidecar，并在后台发布健康检查通过后的动态端口。
272: fn start_sidecar(app: &AppHandle) -> Result<u16, String> {
273:     let port = pick_free_port();
274:     info!("分配后端动态端口：{port}");
275: 
276:     let sidecar = app
277:         .shell()
278:         .sidecar("butvan-backend")
279:         .map_err(|e| e.to_string())?;
280:     let (mut rx, child) = sidecar
281:         .args([
282:             format!("--server.port={port}"),
283:             "--server.address=127.0.0.1".to_string(),
284:         ])
285:         .spawn()
286:         .map_err(|e| format!("后端 sidecar 启动失败：{e}"))?;
287: 
288:     let state = app.state::<BackendState>();
289:     *state.child.lock().unwrap() = Some(child);
