291:     // 后台线程轮询 /api/health，就绪后把端口写入状态供前端读取
292:     let handle = app.clone();
293:     thread::spawn(move || {
294:         let ready = wait_until_ready(port, Duration::from_secs(60));
295:         if ready {
296:             if let Some(state) = handle.try_state::<BackendState>() {
297:                 *state.port.lock().unwrap() = Some(port);
298:             }
299:             info!("后端 sidecar 已就绪，端口：{port}");
300:         } else {
301:             error!("后端 sidecar 60 秒内未就绪，端口：{port}");
302:         }
303:     });
304: 
305:     // 转发子进程标准输出/错误到应用日志，避免管道积压阻塞
306:     tauri::async_runtime::spawn(async move {
307:         while let Some(event) = rx.recv().await {
308:             match event {
309:                 CommandEvent::Stdout(line) | CommandEvent::Stderr(line) => {
310:                     let text = String::from_utf8_lossy(&line);
311:                     let text = text.trim_end();
