343: /// 轮询后端健康检查接口，直到返回 HTTP 200 或超时
344: fn wait_until_ready(port: u16, timeout: Duration) -> bool {
345:     let deadline = Instant::now() + timeout;
346:     while Instant::now() < deadline {
347:         if probe_health(port) {
348:             return true;
349:         }
350:         thread::sleep(Duration::from_millis(400));
351:     }
352:     false
353: }
