355: /// 向 /api/health 发送最小 HTTP GET 请求，返回是否收到 200 响应
356: fn probe_health(port: u16) -> bool {
357:     let Ok(addr) = format!("127.0.0.1:{port}").parse::<std::net::SocketAddr>() else {
358:         return false;
359:     };
360:     let Ok(mut stream) = TcpStream::connect_timeout(&addr, Duration::from_millis(400)) else {
361:         return false;
362:     };
363:     let _ = stream.set_read_timeout(Some(Duration::from_millis(400)));
364: 
365:     let request =
366:         format!("GET /api/health HTTP/1.1\r\nHost: 127.0.0.1:{port}\r\nConnection: close\r\n\r\n");
367:     if stream.write_all(request.as_bytes()).is_err() {
368:         return false;
369:     }
370: 
371:     let mut buf = [0u8; 256];
372:     let Ok(n) = stream.read(&mut buf) else {
373:         return false;
374:     };
375:     String::from_utf8_lossy(&buf[..n]).starts_with("HTTP/1.1 200")
376: }

